const sectionCards = (templates: DesignTemplate[], labels: string[]): HomeSectionCard[] =>
  templates.slice(0, 7).map((template, index) => ({
    id: template.id,
    label: labels[index] ?? template.title,
    templateId: template.id,
    title: template.title,
    coverUrl: template.coverUrl,
    width: template.width,
    height: template.height,
    isFree: template.isFree,
  }))

